**suggestion (performance):** Background process output is stored in arrays, which may grow unbounded.

Implement a limit on buffer size or periodic cleanup to prevent memory issues when handling large or numerous background process outputs.

```suggestion
        // Limit for stdout/stderr buffer size (number of entries)
        const MAX_OUTPUT_BUFFER = 1000;

        const shellProcess: ShellProcess = {
          lastRead: 0,
          process: childProcess,
          stderr: [],
          stdout: [],
        };

        // Capture output with buffer limit
        childProcess.stdout?.on('data', (data) => {
          shellProcess.stdout.push(data.toString());
          if (shellProcess.stdout.length > MAX_OUTPUT_BUFFER) {
            shellProcess.stdout.splice(0, shellProcess.stdout.length - MAX_OUTPUT_BUFFER);
          }
        });

        childProcess.stderr?.on('data', (data) => {
          shellProcess.stderr.push(data.toString());
          if (shellProcess.stderr.length > MAX_OUTPUT_BUFFER) {
            shellProcess.stderr.splice(0, shellProcess.stderr.length - MAX_OUTPUT_BUFFER);
          }
        });
```

